import{_ as t,o as a,c as d,a4 as n}from"./chunks/framework.CzJ_HCFe.js";const m=JSON.parse('{"title":"Engines and the PanchangamDay computation contract","description":"","frontmatter":{},"headers":[],"relativePath":"reference/02-engines-and-model.md","filePath":"reference/02-engines-and-model.md","lastUpdated":1788519103000}'),o={name:"reference/02-engines-and-model.md"};function i(s,e,r,c,l,h){return a(),d("div",null,[...e[0]||(e[0]=[n(`<h1 id="engines-and-the-panchangamday-computation-contract" tabindex="-1">Engines and the <code>PanchangamDay</code> computation contract <a class="header-anchor" href="#engines-and-the-panchangamday-computation-contract" aria-label="Permalink to &quot;Engines and the \`PanchangamDay\` computation contract&quot;">​</a></h1><p>This document describes what the repository computes today. It is not a claim that every convention is textually authoritative or independently verified. Evidence states come from <a href="provenance.json"><code>provenance.json</code></a>; stable computation IDs come from <a href="computations.json"><code>computations.json</code></a>.</p><h2 id="assurance-key" tabindex="-1">Assurance key <a class="header-anchor" href="#assurance-key" aria-label="Permalink to &quot;Assurance key&quot;">​</a></h2><ul><li><strong>Source-traced</strong> means the implementation has an inspected technical or textual source with an exact locator.</li><li><strong>Independently compared</strong> means a value was checked against a separate published result for the same date and location.</li><li><strong>Regression-pinned</strong> means tests preserve current output. It does not prove that the output is correct outside those test cells.</li><li><strong>Unresolved</strong> means the implementation or convention still needs source or comparison work. The gap is named rather than hidden.</li></ul><p>The current high-level evidence states are:</p><table tabindex="0"><thead><tr><th>Layer</th><th>State</th><th>Provenance claim</th></tr></thead><tbody><tr><td>Drik sidereal positions</td><td>Partially verified</td><td><code>drik.sidereal_positions</code></td></tr><tr><td>Surya Siddhanta longitude model</td><td>Source-traced in part; output engine-pinned</td><td><code>surya_siddhanta.mean_motion_manda</code>, <code>panchangam.non_drik_engine_outputs</code></td></tr><tr><td>Vakya longitude model</td><td>Provisional and engine-pinned</td><td><code>vakya.provisional_lunar_model</code></td></tr><tr><td>Rise/set convention</td><td>Implementation traced; target convention unresolved</td><td><code>panchangam.rise_set_convention</code></td></tr><tr><td>Calendar naming and rollover semantics</td><td>Needs criterion-level locators</td><td><code>panchangam.calendar_semantics</code></td></tr><tr><td>Daily windows</td><td>Mixed, partially verified container</td><td><code>panchangam.mixed_daily_windows</code></td></tr></tbody></table><h2 id="end-to-end-calculation" tabindex="-1">End-to-end calculation <a class="header-anchor" href="#end-to-end-calculation" aria-label="Permalink to &quot;End-to-end calculation&quot;">​</a></h2><p>For <code>calculate(date, location, include_eclipse)</code> each engine follows this flow:</p><ol><li><code>local_midnight_jd</code> localizes civil midnight in <code>location.timezone</code>, converts it to UTC and then to a Universal-Time Julian day.</li><li>Shared Swiss Ephemeris helpers find the first sunrise and Moon rise/set after that local midnight, sunset after sunrise, and the next sunrise from the next local midnight.</li><li>The selected engine evaluates Sun and Moon longitudes at sunrise.</li><li>The engine derives the five angas, their applicable spans, signs, Paksham, Maasam, Samvatsara and special-day flags.</li><li>Shared helpers derive windows, festivals and additive classifications.</li><li>The result is returned as <code>PanchangamDay</code>. Datetimes are timezone-aware UTC; presentation layers convert them for display.</li></ol><p>The three <code>calculate</code> methods are separate implementations, not a single shared calculation method. The base class owns shared helpers and per-instant <code>facts_at</code>, but it does not derive the complete day from two polymorphic longitude functions. This distinction matters when comparing the engines.</p><h2 id="time-units-and-boundary-contract" tabindex="-1">Time, units and boundary contract <a class="header-anchor" href="#time-units-and-boundary-contract" aria-label="Permalink to &quot;Time, units and boundary contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Current behavior</th></tr></thead><tbody><tr><td>Input date</td><td>A civil <code>date</code> interpreted in the supplied IANA timezone.</td></tr><tr><td>Core time scale</td><td>Universal-Time Julian day as a floating-point number. One unit is one day.</td></tr><tr><td>Returned datetimes</td><td>UTC, timezone-aware, truncated to whole seconds by <code>jd_to_utc</code>; not rounded.</td></tr><tr><td>Panchangam day</td><td>Most day windows use <code>[sunrise, next sunrise)</code>. Daytime windows use <code>[sunrise, sunset]</code>. The stored <code>date</code> remains the input civil date.</td></tr><tr><td>Longitude</td><td>Degrees normalized to <code>[0, 360)</code>.</td></tr><tr><td>Span transitions</td><td>Located with <code>find_crossing</code>, at most 60 bisections and a default Julian-day tolerance of <code>1e-8</code> (about 0.864 ms), then exposed at whole-second precision.</td></tr><tr><td>Weekday</td><td><code>int(jd_sunrise + 1.5) % 7</code>, where 0 is Sunday; it is fixed for the Panchangam day.</td></tr><tr><td>High-latitude failures</td><td>Swiss Ephemeris return codes are currently ignored. The configured city set avoids polar no-event cases, but the helper contract does not safely represent them.</td></tr></tbody></table><h3 id="rise-and-set-are-shared-not-engine-specific" tabindex="-1">Rise and set are shared, not engine-specific <a class="header-anchor" href="#rise-and-set-are-shared-not-engine-specific" aria-label="Permalink to &quot;Rise and set are shared, not engine-specific&quot;">​</a></h3><p><code>get_sunrise</code>, <code>get_sunset</code>, <code>get_moonrise</code> and <code>get_moonset</code> call Swiss Ephemeris <code>rise_trans</code> for all three systems. The call currently uses:</p><ul><li>only <code>CALC_RISE</code> or <code>CALC_SET</code>;</li><li>longitude and latitude, with altitude forced to <code>0.0</code> metres;</li><li>pressure <code>1013.25</code> hPa and temperature <code>15.0</code> °C;</li><li>the default astronomical upper-limb/refraction convention.</li></ul><p>Swiss Ephemeris Programmer&#39;s Documentation sections 8.12 and 8.12.1 distinguish that default from its Hindu-calendar disc-centre/no-refraction mode. The project has not yet recorded a multi-city comparison that decides which convention its public Panchangam should promise. That work is tracked in <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/177" target="_blank" rel="noreferrer">#177</a>. Until it is resolved, do not describe these four fields as a verified Hindu sunrise convention.</p><p>Technical source: <a href="https://www.astro.com/swisseph/swephprg.htm" target="_blank" rel="noreferrer">Swiss Ephemeris Programmer&#39;s Documentation</a>, sections 3, 5.8, 8.12, 8.12.1 and 12.2.</p><h2 id="the-three-longitude-models" tabindex="-1">The three longitude models <a class="header-anchor" href="#the-three-longitude-models" aria-label="Permalink to &quot;The three longitude models&quot;">​</a></h2><h3 id="drik-ganita" tabindex="-1">Drik Ganita <a class="header-anchor" href="#drik-ganita" aria-label="Permalink to &quot;Drik Ganita&quot;">​</a></h3><p>Owner: <code>DrikGanitaEngine</code> in <code>telugu_panchangam/engines/drik.py</code>.</p><p><code>_sun_lon</code> and <code>_moon_lon</code> call Swiss Ephemeris <code>calc_ut</code> with <code>FLG_SWIEPH | FLG_SIDEREAL</code>, returning geocentric ecliptic longitude under the selected sidereal mode. Lahiri is the default and uses cached helpers. Raman, Krishnamurti and True Chitrapaksha bypass that cache, set the requested global Swiss sidereal mode, calculate the longitude and restore Lahiri afterward.</p><p>The selected ayanamsa changes Drik Sun/Moon longitudes and downstream angas, signs, Maasam and ingress times. It also changes the Drik-only Jupiter and Venus positions used for Simha-stha and Maudhya. The Swiss documentation supports the API and flag semantics; representative repository tests and published day cells support only partial output verification.</p><h3 id="surya-siddhanta" tabindex="-1">Surya Siddhanta <a class="header-anchor" href="#surya-siddhanta" aria-label="Permalink to &quot;Surya Siddhanta&quot;">​</a></h3><p>Owner: <code>SuryaSiddhantaEngine</code> in <code>telugu_panchangam/engines/surya_siddhanta.py</code>.</p><p>The implementation is a bounded modern transcription of mean motion plus one manda correction, not a complete implementation of every Sūrya Siddhānta procedure:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ahargana       = jd - 588465.5</span></span>
<span class="line"><span>mean_longitude = (ahargana * revolutions / 1,577,917,828 * 360) mod 360</span></span>
<span class="line"><span>anomaly        = (mean_longitude - apogee) mod 360</span></span>
<span class="line"><span>circumference  = even - (even - odd) * abs(sin(anomaly))</span></span>
<span class="line"><span>manda          = asin((circumference / 360) * sin(anomaly))</span></span>
<span class="line"><span>true_longitude = (mean_longitude - manda) mod 360</span></span></code></pre></div><p>The Sun uses 4,320,000 revolutions, a fixed apogee of 77.333° and epicycle circumferences 14°/13°40′. The Moon uses 57,753,336 revolutions, a moving apogee of 488,219 revolutions plus 90° at the code epoch, and circumferences 32°/31°40′.</p><p>The source crosswalk is Ebenezer Burgess and William Dwight Whitney, <em>Translation of the Sûrya-Siddhânta</em>, Journal of the American Oriental Society 6 (1860): chapter I verses 29–34 and 53 for revolution counts and mean place; chapter II verses 29–39 for anomaly, epicycle dimensions and manda equation. The code uses direct floating-point trigonometry and fixed/simplified constants, so this locator supports the algorithm family, not a claim of complete textual fidelity or modern astronomical accuracy.</p><p>Tests bound the 2026 sample Sun difference from the Drik model below 1° and the Moon difference below 5.5°. That is a cross-model regression check, not an independent published Surya Siddhanta Panchangam comparison.</p><p>The constructor accepts an ayanamsa name for API symmetry and validation, but the selected name does not change any Surya Siddhanta output.</p><h3 id="vakya" tabindex="-1">Vakya <a class="header-anchor" href="#vakya" aria-label="Permalink to &quot;Vakya&quot;">​</a></h3><p>Owner: <code>VakyaEngine</code> in <code>telugu_panchangam/engines/vakya.py</code>.</p><p>The current implementation keeps the Surya Siddhanta Sun and adds one of nine offsets (<code>0</code>, <code>+0.5</code>, <code>+1</code>, <code>+0.5</code>, <code>0</code>, <code>-0.5</code>, <code>-1</code>, <code>-0.5</code>, <code>0</code> degrees) to the Surya Siddhanta Moon. The phase index is <code>int(abs(jd - 588465.5) / 3031) % 9</code>.</p><p>This is a provisional project model. It is not a registered transcription of a 248-entry lunar-vākya table, and 3,031 days must not be described as a 248-year cycle. Source reconstruction and a possible frozen-core correction are tracked in <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/176" target="_blank" rel="noreferrer">#176</a>. Current tests prove range, shape and regression behavior only.</p><p>Like Surya Siddhanta, Vakya accepts but does not apply the ayanamsa parameter.</p><h2 id="pancha-anga-formulas-and-transition-spans" tabindex="-1">Pancha anga formulas and transition spans <a class="header-anchor" href="#pancha-anga-formulas-and-transition-spans" aria-label="Permalink to &quot;Pancha anga formulas and transition spans&quot;">​</a></h2><p>Let <code>S</code> be the engine&#39;s Sun longitude, <code>M</code> its Moon longitude and <code>E = (M - S) mod 360</code> at a Universal-Time Julian day.</p><table tabindex="0"><thead><tr><th>Anga</th><th>Sunrise value</th><th>Stored transition semantics</th><th>Owners</th></tr></thead><tbody><tr><td>Tithi</td><td><code>floor(E / 12°) mod 30</code></td><td><code>tithi</code> is the Tithi active at sunrise. Start is bisected in <code>[sunrise-2d, sunrise]</code>; end in <code>[sunrise, sunrise+2d]</code>.</td><td>Engine <code>_tithi_index_at</code>, <code>_tithi_span</code></td></tr><tr><td>Vaaram</td><td>Sunrise Julian weekday</td><td><code>vaaram</code> is one name for the entire Panchangam day; it does not flip at civil midnight.</td><td>each engine <code>calculate</code></td></tr><tr><td>Nakshatra</td><td><code>floor(M / (360°/27)) mod 27</code></td><td><code>nakshatra</code> is active at sunrise. Start/end use the engine&#39;s Moon model and ±2-day search windows.</td><td>engine <code>_nakshatra_span</code></td></tr><tr><td>Nitya Yoga</td><td><code>floor(((S+M) mod 360) / (360°/27)) mod 27</code></td><td><code>yoga</code> is active at sunrise with the same ±2-day crossing windows.</td><td>engine <code>_yoga_span</code></td></tr><tr><td>Karana</td><td><code>floor(E / 6°) mod 60</code></td><td>Up to two spans intersecting sunrise–sunset are returned in <code>karana</code>. Spans are not clipped to the daylight interval. Fixed and sevenfold repeating names come from <code>panchangam_names.py</code>.</td><td>engine <code>_karana_spans</code></td></tr></tbody></table><p><code>facts_at</code> derives the same five instant-level names from an engine&#39;s exposed Sun/Moon functions. Callers must pass the day&#39;s <code>vaaram</code>; its UTC-weekday fallback is explicitly approximate around the sunrise/civil-day boundary.</p><h2 id="calendar-metadata" tabindex="-1">Calendar metadata <a class="header-anchor" href="#calendar-metadata" aria-label="Permalink to &quot;Calendar metadata&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fields</th><th>Algorithm</th><th>Implementation</th><th>Evidence state</th></tr></thead><tbody><tr><td><code>solar_sign</code>, <code>lunar_sign</code></td><td>Sunrise longitude divided into twelve 30° Rasis.</td><td>each engine <code>calculate</code></td><td>Follows the engine position state.</td></tr><tr><td><code>paksham</code></td><td>Tithi indices 0–14 are Shukla; 15–29 are Krishna.</td><td>each engine <code>calculate</code></td><td><code>panchangam.calendar_semantics</code>; locator debt remains.</td></tr><tr><td><code>maasam</code></td><td>Find bounding new moons from the engine elongation; name by the Sun sign at the starting new moon. Same Sun sign at start/end gives <code>Adhika</code>; same sign at previous/start gives <code>Nija</code>.</td><td><code>maasam_name</code>, engine <code>_maasam</code></td><td>Needs regional criterion-level verification.</td></tr><tr><td><code>samvatsara</code></td><td>Count 365.25636-day years from JD 588465.5, shift by the lunar-month number so the label flips at Chaitra, then apply offset 12 modulo 60.</td><td><code>samvatsara_name</code></td><td>Project convention; needs exact locator.</td></tr><tr><td><code>ayanam</code></td><td>Sidereal Sun signs Makara through Mithuna map to Uttarayanam; Karkataka through Dhanu to Dakshinayanam.</td><td><code>ayanam_name</code></td><td>Needs exact criterion locator.</td></tr><tr><td><code>rituvu</code></td><td>Tropical Swiss Ephemeris Sun sign selects the six-season name.</td><td><code>rituvu_name</code></td><td>Hybrid: all three engines use the same Drik/tropical helper.</td></tr></tbody></table><p>New-moon search uses a 12.19°/day iterative estimate for ten iterations and a fixed 29.530589-day fallback. Its result is an implementation technique, not a separately verified astronomical event series.</p><h2 id="core-windows" tabindex="-1">Core windows <a class="header-anchor" href="#core-windows" aria-label="Permalink to &quot;Core windows&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fields</th><th>Current calculation</th><th>Boundary notes</th></tr></thead><tbody><tr><td><code>rahu_kalam</code>, <code>gulika_kalam</code>, <code>yamagandam</code></td><td>Weekday-selected one-eighth of sunrise–sunset.</td><td>Equal temporal eighths; tables use Sunday index 0.</td></tr><tr><td><code>brahma_muhurta</code></td><td>96 to 48 clock minutes before sunrise.</td><td>Uses fixed fractions of a 24-hour Julian day.</td></tr><tr><td><code>abhijit_muhurta</code></td><td>Local daylight midpoint ± one-thirtieth of daylight.</td><td>Omitted on Wednesday; total length is one-fifteenth of daylight.</td></tr><tr><td><code>choghadiya</code></td><td>Eight equal daytime blocks with weekday names.</td><td>Night Choghadiya is not returned.</td></tr><tr><td><code>durmuhurtham</code></td><td>Weekday-selected parts of fifteen equal daylight divisions; Tuesday also uses the seventh of fifteen night divisions.</td><td>Night is sunset–next sunrise.</td></tr><tr><td><code>varjyam</code>, <code>amrita_kalam</code></td><td>Four-sixtieths of the actual Nakshatra span, starting at its configured ghati.</td><td>Consider the sunrise Nakshatra and its successor; return a window only when its start falls in <code>[sunrise, next sunrise)</code>.</td></tr></tbody></table><p>These fields form a mixed-evidence container. The exact Raman locators in <code>panchangam.mixed_daily_windows</code> cover Nakshatra Tyajyakala and a Durmuhurta scheme, while other tables and regional differences remain partially verified or regression-pinned.</p><h2 id="festival-deciding-moments" tabindex="-1">Festival deciding moments <a class="header-anchor" href="#festival-deciding-moments" aria-label="Permalink to &quot;Festival deciding moments&quot;">​</a></h2><p><code>PanchangamEngine._festivals</code> applies shared rule tables using the selected engine&#39;s Tithi and Maasam. Its moment semantics are exact implementation contracts:</p><table tabindex="0"><thead><tr><th>Rule family</th><th>Deciding instant</th></tr></thead><tbody><tr><td>Sunrise</td><td>sunrise</td></tr><tr><td>Madhyahna</td><td><code>sunrise + 0.5 * daylight</code></td></tr><tr><td>Aparahna</td><td><code>sunrise + 0.7 * daylight</code></td></tr><tr><td>Pradosha</td><td><code>sunset + 0.05</code> Julian day (72 clock minutes)</td></tr><tr><td>Nishita</td><td>midpoint of sunset and next sunrise</td></tr><tr><td>Monthly Moonrise</td><td>Moonrise when it falls between sunset and next sunrise; otherwise <code>sunset + 0.1</code> Julian day</td></tr><tr><td>Weekday in Maasam</td><td>sunrise Maasam plus sunrise weekday</td></tr><tr><td>Last weekday in Paksha</td><td>current sunrise Paksha differs from the same weekday seven days later</td></tr><tr><td>Solar ingress</td><td>between sunrise and sunset belongs to that day; after the previous sunset belongs to the next day</td></tr></tbody></table><p>Moment-based rules compare the same instant one Julian day earlier to avoid double assignment when a Tithi spans two deciding instants. Adhika months skip the annual lunar festival tables but still admit the monthly vrata tables.</p><p>The forward-year fixture contains a mixture of independently checked and engine-pinned cells. Consult each fixture cell&#39;s label; never describe the whole festival series as independently verified.</p><h2 id="engine-asymmetries-and-hybrids" tabindex="-1">Engine asymmetries and hybrids <a class="header-anchor" href="#engine-asymmetries-and-hybrids" aria-label="Permalink to &quot;Engine asymmetries and hybrids&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Drik</th><th>Surya Siddhanta</th><th>Vakya</th></tr></thead><tbody><tr><td>Sun/Moon longitude</td><td>Swiss sidereal mode</td><td>Project SS mean-motion/manda model</td><td>SS Sun plus provisional Moon offset</td></tr><tr><td>Ayanamsa parameter</td><td>Applied</td><td>Validated, no effect</td><td>Validated, no effect</td></tr><tr><td>Pancha anga spans</td><td>Drik-specific methods</td><td>SS-specific methods</td><td>Vakya overrides every Moon-dependent method</td></tr><tr><td>Rise/set</td><td>Shared Swiss default</td><td>Shared Swiss default</td><td>Shared Swiss default</td></tr><tr><td>Rituvu</td><td>Shared tropical Swiss Sun</td><td>Shared tropical Swiss Sun</td><td>Shared tropical Swiss Sun</td></tr><tr><td>Eclipse</td><td>Shared Swiss eclipse calculation</td><td>Shared Swiss eclipse calculation</td><td>Shared Swiss eclipse calculation</td></tr><tr><td>Jupiter/Venus flags</td><td>Populated</td><td>Default <code>False</code>/<code>None</code></td><td>Default <code>False</code>/<code>None</code></td></tr><tr><td>Festivals and windows</td><td>Shared rules fed by Drik facts</td><td>Shared rules fed by SS facts</td><td>Shared rules fed by Vakya facts</td></tr></tbody></table><p>Consequently, “Surya Siddhanta day” and “Vakya day” do not mean that every field comes from that astronomical system. Rise/set, Rituvu and eclipse fields are deliberately shared Swiss-derived hybrids.</p><h2 id="panchangamday-field-to-owner-map" tabindex="-1"><code>PanchangamDay</code> field-to-owner map <a class="header-anchor" href="#panchangamday-field-to-owner-map" aria-label="Permalink to &quot;\`PanchangamDay\` field-to-owner map&quot;">​</a></h2><p>Every current model field appears below. “Default” means the dataclass supplies the initial value until an engine or finalizer replaces it.</p><table tabindex="0"><thead><tr><th>Field group</th><th>Fields</th><th>Immediate owner</th></tr></thead><tbody><tr><td>Request identity</td><td><code>date</code>, <code>location</code>, <code>system</code></td><td>engine <code>calculate</code></td></tr><tr><td>Calendar metadata</td><td><code>samvatsara</code>, <code>ayanam</code>, <code>rituvu</code>, <code>maasam</code>, <code>paksham</code></td><td>engine <code>calculate</code>; shared naming helpers</td></tr><tr><td>Five angas</td><td><code>tithi</code>, <code>vaaram</code>, <code>nakshatra</code>, <code>yoga</code>, <code>karana</code></td><td>engine-specific span methods and <code>calculate</code></td></tr><tr><td>Sky and signs</td><td><code>sunrise</code>, <code>sunset</code>, <code>moonrise</code>, <code>moonset</code>, <code>solar_sign</code>, <code>lunar_sign</code></td><td>shared rise/set helpers plus engine sunrise longitudes</td></tr><tr><td>Auspicious windows</td><td><code>brahma_muhurta</code>, <code>abhijit_muhurta</code>, <code>amrita_kalam</code></td><td>base window helpers</td></tr><tr><td>Inauspicious windows</td><td><code>rahu_kalam</code>, <code>gulika_kalam</code>, <code>yamagandam</code>, <code>varjyam</code>, <code>durmuhurtham</code></td><td>base window helpers</td></tr><tr><td>Choghadiya</td><td><code>choghadiya</code></td><td><code>_choghadiya</code></td></tr><tr><td>Tithi/day flags</td><td><code>is_ekadashi</code>, <code>is_amavasya</code>, <code>is_pournami</code>, <code>is_pradosham</code>, <code>is_shani_pradosham</code>, <code>is_soma_pradosham</code>, <code>is_sankranti</code></td><td>engine <code>_special_flags</code></td></tr><tr><td>Events</td><td><code>special_notes</code>, <code>eclipse</code>, <code>special_yogas</code>, <code>festivals</code>, <code>sankramanam</code></td><td>default; eclipse/special-yoga modules; base festival/ingress helpers</td></tr><tr><td>Ghati and Karana additions</td><td><code>ghati_clock</code>, <code>nakshatra_pada</code>, <code>vishaghati</code>, <code>bhadra_mukha</code>, <code>bhadra_puchha</code></td><td><code>_finalize_day</code>, <code>ghati.py</code>, <code>karana_windows.py</code></td></tr><tr><td>Sankramana and month filters</td><td><code>sankramana_avoidance</code>, <code>in_panchaka_nakshatra</code>, <code>is_khar_maasa</code>, <code>khar_maasa_name</code>, <code>is_pitru_paksha</code></td><td><code>_finalize_day</code> and dedicated derived modules</td></tr><tr><td>Drik-only outer-planet fields</td><td><code>simha_stha_guru</code>, <code>simha_stha_shukra</code>, <code>guru_maudhya</code>, <code>shukra_maudhya</code></td><td>Drik <code>calculate</code>; dataclass defaults for SS/Vakya</td></tr><tr><td>Other derived classifications</td><td><code>anandadi_yoga</code>, <code>disha_shoola_direction</code>, <code>nakshatra_mukha</code>, <code>panchaka_rahita</code></td><td><code>_finalize_day</code> and dedicated derived modules</td></tr></tbody></table><p>The derived rules in the last four rows are documented in <a href="./03-computational-features">Computational features</a> and will receive their own criterion-level evidence audit under story #167. This document records their ownership so no model field is orphaned.</p><h2 id="representative-test-map" tabindex="-1">Representative test map <a class="header-anchor" href="#representative-test-map" aria-label="Permalink to &quot;Representative test map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Contract</th><th>Tests</th></tr></thead><tbody><tr><td>Drik day, angas, signs, metadata and ingress</td><td><code>tests/test_drik_engine.py</code>, <code>tests/test_integration.py</code></td></tr><tr><td>Ayanamsa application and no-op boundaries</td><td><code>tests/test_ayanamsa.py</code></td></tr><tr><td>Surya Siddhanta day and cross-model longitude bounds</td><td><code>tests/test_surya_siddhanta_engine.py</code></td></tr><tr><td>Vakya day and provisional-offset regression</td><td><code>tests/test_vakya_engine.py</code></td></tr><tr><td>Shared windows and Maasam helpers</td><td><code>tests/test_base.py</code>, <code>tests/test_muhurta_windows.py</code></td></tr><tr><td>Festival rules and deciding moments</td><td><code>tests/test_festivals.py</code>, <code>tests/test_festivals_forward_year.py</code></td></tr><tr><td>Per-instant facts</td><td><code>tests/test_engine_facts_at.py</code></td></tr><tr><td>Model shape</td><td><code>tests/test_models.py</code></td></tr><tr><td>This documentation&#39;s links, symbols, fields and claims</td><td><code>tests/test_engine_documentation.py</code></td></tr></tbody></table><h2 id="review-checklist" tabindex="-1">Review checklist <a class="header-anchor" href="#review-checklist" aria-label="Permalink to &quot;Review checklist&quot;">​</a></h2><p>When an engine-facing computation changes:</p><ol><li>Update the stable computation record and this contract in the same PR.</li><li>State whether the result is regression-pinned, source-traced or independently compared; do not promote one state into another.</li><li>Add exact date, location, system, timezone, input convention and expected value to comparison fixtures.</li><li>Preserve UTC internally and make any display-time conversion explicit.</li><li>Treat changes under <code>telugu_panchangam/engines/</code> as frozen-core changes that require owner approval, focused tests, the full project gate and a PyPI version bump.</li></ol>`,62)])])}const p=t(o,[["render",i]]);export{m as __pageData,p as default};
